fn insert_before_each(arr: &Vec<i32>, elem: i32) -> Vec<i32> {
    // Pre-allocate a vector with twice the capacity of the input
    let mut result = Vec::with_capacity(arr.len() * 2);

    // For each item in the input, push `elem` first, then the item.
    for &x in arr {
        result.push(elem);
        result.push(x);
    }

    result
}

